import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == -1) break;

            long oddSum = 0;
            long evenSum = 0;

            for (int i = 0; i < n; i++) {
                int num = sc.nextInt();
                if (num % 2 == 0) {
                    evenSum += num;
                } else {
                    oddSum += num;
                }
            }

            if (oddSum > evenSum) {
                System.out.println("Odd Sum Greater");
            } else {
                System.out.println("Even Sum Greater");
            }
        }

        sc.close();
    }
}
